<?php
declare(strict_types=1);
namespace QualitySystem\Controllers;
require_once dirname(__DIR__,2).'/security.php';
use PDO;use QualitySystem\Repositories\ProgramSpecificationRepository;use QualitySystem\Security\PermissionMatrix;use QualitySystem\Services\ProgramSpecificationService;use QualitySystem\Services\ProgramSpecificationValidationException;
final class ProgramSpecificationController
{
    private ProgramSpecificationRepository $repository;private ProgramSpecificationService $service;
    public function __construct(PDO $pdo,private readonly string $root){$this->repository=new ProgramSpecificationRepository($pdo);$this->service=new ProgramSpecificationService($pdo,$this->repository);}
    public function dispatch(string $path,string $method):void{$role=(string)($_SESSION['role']??'');$userId=(int)($_SESSION['user_id']??0);if(!PermissionMatrix::allows($role,'programs','view'))$this->abort(403,'Access denied.');if($path==='/program-specifications'&&$method==='GET'){$this->index($role,$userId);return;}if($path==='/program-specifications/create'){if(!PermissionMatrix::allows($role,'programs','create'))$this->abort(403,'Access denied.');$method==='POST'?$this->save(null,$role,$userId):$this->form(null,$role,$userId);return;}if(preg_match('#^/program-specifications/(\d+)/edit$#',$path,$m)){if(!PermissionMatrix::allows($role,'programs','update'))$this->abort(403,'Access denied.');$method==='POST'?$this->save((int)$m[1],$role,$userId):$this->form((int)$m[1],$role,$userId);return;}if(preg_match('#^/program-specifications/(\d+)/delete$#',$path,$m)&&$method==='POST'){try{$this->service->delete((int)$m[1],$role,$userId);header('Location: /program-specifications');}catch(\RuntimeException $e){$this->abort(in_array($e->getCode(),[403,404,409],true)?$e->getCode():500,$e->getMessage());}return;}$this->abort(404,'Not found.');}
    private function index(string $role,int $userId):void{$page=max(1,(int)($_GET['page']??1));$perPage=min(50,max(10,(int)($_GET['per_page']??20)));$filters=['search'=>mb_substr(trim((string)($_GET['search']??'')),0,100),'approval_status'=>mb_substr(trim((string)($_GET['approval_status']??'')),0,30),'specification_type'=>mb_substr(trim((string)($_GET['specification_type']??'')),0,30)];$result=$this->repository->paginate($role,$userId,$page,$perPage,$filters);$this->render('program_specifications/index',$result+compact('page','perPage','filters','role'));}
    private function form(?int $id,string $role,int $userId,array $errors=[],array $input=[]):void{$spec=$id!==null?$this->repository->findScoped($id,$role,$userId):[];if($id!==null&&!$spec)$this->abort(404,'Program specification not found.');if($input)$spec=array_merge($spec,$input);$this->render('program_specifications/form',['spec'=>$spec,'errors'=>$errors,'studyPlans'=>$this->repository->studyPlans(),'role'=>$role]);}
    private function save(?int $id,string $role,int $userId):void{try{$saved=$this->service->save($_POST,$role,$userId,$id);header('Location: /program-specifications');}catch(ProgramSpecificationValidationException $e){http_response_code(422);$this->form($id,$role,$userId,$e->errors,$_POST);}catch(\RuntimeException $e){$this->abort(in_array($e->getCode(),[403,404],true)?$e->getCode():500,$e->getMessage());}}
    private function render(string $template,array $data):void{extract($data,EXTR_SKIP);require$this->root.'/templates/'.$template.'.php';}
    private function abort(int $status,string $message):never{http_response_code($status);exit(htmlspecialchars($message,ENT_QUOTES,'UTF-8'));}
}
